+	defer b.mu.Unlock()
+	if c.closed {
+		return nil
+	}
+	c.closed = true
+	delete(b.cursors, c)
+	if !b.closed {
+		b.reclaimLocked()
+	}
+	b.wakeLocked()
+	return nil
+}
+
+func (b *Buffer[T]) wakeLocked() {
+	close(b.notify)
+	b.notify = make(chan struct{})
+}
+
+func (b *Buffer[T]) expireLocked() {
+	now := b.cfg.Clock.Now()
+	changed := false
+	for c := range b.cursors {
+		b.updateLagLocked(c, now)
+		if !c.behindSince.IsZero() && now.Sub(c.behindSince) >= b.cfg.GracePeriod {
+			c.expired = true
+			delete(b.cursors, c)
+			changed = true
+		}
+	}
+	if changed {
+		b.reclaimLocked()
+		b.wakeLocked()
+	}
